// Turns an agent reply into a Telegram card (HTML parse mode): agent header, emoji section titles, bullets,
// and the cards built by code from Notion (item.progress: goals, tasks, subtasks; item.budget: budget lines).
// The agent's text never repeats a card: the card is the only list. Nothing on a card is shortened or left out:
// a reply too long for one message is split between whole lines into a second message (telegram_rest).
// Every piece of model text is escaped and every tag opens and closes on its own line, so the message is
// shortened only between lines and a tag can never be left open. The ➡️ hand-off line always stays last,
// because the Router reads it at the end of the message.
const item = $input.item.json;
// A "[card: ...]" line is the agent's instruction to its workflow, never shown
const original = String(item.output ?? '').replace(/\r\n?/g, '\n').replace(/^\s*\[card:[^\]\n]*\]\s*$/gim, '').trim();
const agent = String(item.agent_name || '');
const LIMIT = 3800;

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = (s) => esc(s).replace(/"/g, '&quot;');
// Inline markdown: code and links are set aside first, then bold, so no two tags can overlap
const inline = (raw) => {
  const keep = [];
  const hold = (html) => '\u0000' + (keep.push(html) - 1) + '\u0000';
  let s = String(raw)
    .replace(/\u0000/g, '')
    .replace(/`([^`\n]+)`/g, (m, c) => hold('<code>' + esc(c) + '</code>'))
    .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, (m, t, u) => hold('<a href="' + escAttr(u) + '">' + esc(t.replace(/\*\*|__/g, '')) + '</a>'));
  s = esc(s)
    .replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>')
    .replace(/__([^_\n]+?)__/g, '<b>$1</b>')
    .replace(/\*\*/g, '');
  return s.replace(/\u0000(\d+)\u0000/g, (m, i) => keep[Number(i)]);
};
const plainOf = (html) => html.replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
const startsWithEmoji = (s) => /^\s*(\p{Extended_Pictographic}|[☀-➿])/u.test(s);

// Error replies: one red mark, nothing else added
const isError = item.error_reason !== undefined || /^⚠️\s*The \S+ agent (did not finish|could not)/.test(original);

const HEAD = { productivity: ['🗓️', 'Productivity'], budget: ['💶', 'Family Budget'], month_setup: ['💶', 'Family Budget'], subscriptions: ['🔁', 'Subscriptions'], project: ['🎯', 'Projects'] };
const DIV = '━━━━━━━━━━━━━━';
const SECTION = [
  [/priorit|focus/i, '🔥'], [/schedule|time.?block|before 10/i, '🕘'], [/still open|overdue|late|pending|left from|not done/i, '⏳'],
  [/done|completed|accomplish|saved|created|marked|added|booked|updated/i, '✅'], [/watch|warning|over budget|attention/i, '⚠️'],
  [/today|tomorrow|next|this week|upcoming|day by day|monday|tuesday|wednesday|thursday|friday|saturday|sunday/i, '🔜'],
  [/goal|project|bet|review|decision/i, '🎯'], [/budget|spent|cap|overall|categor|month/i, '💶'], [/subscription|renew/i, '🔁'],
  [/scratchpad|note|idea/i, '📝'], [/observation|lesson|tip|insight/i, '💡'], [/task|subtask|proposal|propos/i, '📋'],
];
const sectionEmoji = (t) => { for (const [re, e] of SECTION) if (re.test(t)) return e; return '▪️'; };
const bar = (done, total, size, full) => {
  if (!(total > 0)) return '';
  const n = Math.max(0, Math.min(size, Math.round(done / total * size)));
  return full.repeat(n) + '⬜'.repeat(size - n);
};
const budgetBar = (pct) => bar(Math.min(pct, 100), 100, 10, pct >= 100 ? '🟥' : pct >= 80 ? '🟨' : '🟩');
const hasBudgetCard = !!(item.budget && Array.isArray(item.budget.rows) && item.budget.rows.length);
const withBudgetBar = (html, raw, pad) => {
  if ((agent !== 'budget' && agent !== 'month_setup') || hasBudgetCard) return html;
  const m = String(raw).match(/(\d{1,3}(?:[.,]\d+)?)\s?%/);
  return m ? html + '\n' + pad + budgetBar(parseFloat(m[1].replace(',', '.'))) : html;
};

// Split off the hand-off block (from the first ➡️ #agent line to the end)
let lines = original.split('\n');
const hIdx = lines.findIndex((l) => /^\s*➡️?\s*#(productivity|budget|subscriptions|project)\b/i.test(l));
const handoff = hIdx >= 0 ? lines.slice(hIdx).join(' ').replace(/\s+/g, ' ').trim() : '';
if (hIdx >= 0) lines = lines.slice(0, hIdx);

const isTableLine = (l) => /^\s*\|.*\|\s*$/.test(l);
const isSeparator = (l) => /^\s*\|[\s:|-]+\|\s*$/.test(l) && l.includes('-');
const cells = (l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim()).filter((c) => c && c !== '—' && c !== '-');

const body = [];
let structured = false;
if (isError) {
  body.push('🔴 ' + inline(lines.join('\n').trim().replace(/^⚠️\s*/, '')).replace(/\n/g, '\n'));
} else {
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    if (isTableLine(l)) {
      structured = true;
      const hasSep = i + 1 < lines.length && isSeparator(lines[i + 1]);
      if (hasSep) i++; // the header row names the columns; each row below becomes one card line
      else body.push(withBudgetBar('▫️ ' + cells(l).map(inline).join(' · '), l, '      '));
      while (i + 1 < lines.length && isTableLine(lines[i + 1])) {
        i++;
        if (isSeparator(lines[i])) continue;
        const c = cells(lines[i]);
        if (!c.length) continue;
        body.push(withBudgetBar('▫️ <b>' + inline(c[0]) + '</b>' + (c.length > 1 ? ' · ' + c.slice(1).map(inline).join(' · ') : ''), lines[i], '      '));
      }
      continue;
    }
    const heading = l.match(/^\s{0,3}#{1,6}\s+(.*)$/);
    if (heading) {
      structured = true;
      const t = heading[1].replace(/\*\*/g, '').trim();
      const label = /\]\(|`/.test(t) ? inline(t) : inline(t.toUpperCase());
      if (body.length && body[body.length - 1] !== '') body.push('');
      body.push((startsWithEmoji(t) ? '' : sectionEmoji(t) + ' ') + '<b>' + label + '</b>');
      continue;
    }
    const bullet = l.match(/^(\s*)[-*•]\s+(.*)$/);
    if (bullet) {
      structured = true;
      const deep = bullet[1].replace(/\t/g, '  ').length >= 2;
      const pad = deep ? '      ' : '';
      body.push(withBudgetBar(pad + (deep ? '◦ ' : '▫️ ') + inline(bullet[2]), bullet[2], pad + '      '));
      continue;
    }
    const numbered = l.match(/^(\s*)(\d{1,2})[.)]\s+(.*)$/);
    if (numbered) {
      structured = true;
      const pad = numbered[1].length >= 2 ? '      ' : '';
      body.push(withBudgetBar(pad + numbered[2] + '. ' + inline(numbered[3]), numbered[3], pad + '      '));
      continue;
    }
    // A line that is only bold ("**Suggested schedule**") is a small title: emoji only when its words say what it is
    const whole = l.match(/^\s*\*\*([^*\n]+?)\*\*\s*$/);
    if (whole) {
      const t = whole[1].trim();
      const e = startsWithEmoji(t) ? '' : sectionEmoji(t);
      body.push((e && e !== '▪️' ? e + ' ' : '') + '<b>' + inline(t) + '</b>');
      continue;
    }
    // "**Top priorities:** ..." works as a small section title
    const lead = l.match(/^\s*\*\*([^*\n]+?)\*\*(:?)\s*(.*)$/);
    if (lead && (/:$/.test(lead[1].trim()) || lead[2] === ':')) {
      const t = lead[1].trim().replace(/:$/, '');
      body.push((startsWithEmoji(t) ? '' : sectionEmoji(t) + ' ') + '<b>' + inline(t) + ':</b>' + (lead[3] ? ' ' + withBudgetBar(inline(lead[3]), lead[3], '      ') : ''));
      continue;
    }
    if (!l.trim()) { if (body.length && body[body.length - 1] !== '') body.push(''); continue; }
    body.push(withBudgetBar(inline(l), l, ''));
  }
}
while (body.length && body[body.length - 1] === '') body.pop();

// Cards from Notion, built by code in the agent's workflow. Never shortened, never cut.
const ICON = { 'Done': '✅', 'Cancelled': '✖️', 'Working On': '🔄', 'Waiting': '⏳', 'In Progress': '🔄' };
const icon = (s) => ICON[s] || '🔲';
// Tasks card: sections (a day, a range of days, "still open from earlier"), each with weekly goal -> task -> subtasks.
// The older shape {title, goals} is one section titled by its title.
const progressLines = () => {
  const p = item.progress;
  if (!p) return [];
  const sections = Array.isArray(p.sections) ? p.sections : Array.isArray(p.goals) && p.goals.length ? [{ heading: p.title || 'Progress', goals: p.goals }] : [];
  const out = [];
  for (const s of sections) {
    if (!s || !Array.isArray(s.goals) || !s.goals.length) continue;
    if (out.length) out.push('');
    out.push((s.kind === 'overdue' ? '⏳' : '📋') + ' <b>' + esc(String(s.heading || '').toUpperCase()) + '</b>');
    for (const g of s.goals) {
      out.push((g.kind === 'other' ? '📌 <b>' : '🎯 <b>') + esc(g.name) + '</b>');
      if (g.total > 0) out.push('   ' + bar(g.done, g.total, 10, '🟩') + ' ' + g.done + '/' + g.total + ' tasks');
      if (!(g.tasks || []).length) out.push('   <i>' + esc(g.empty || 'no tasks in these days') + '</i>');
      for (const t of g.tasks || []) {
        out.push('   ▫️ ' + icon(t.status) + ' ' + (t.day ? esc(t.day) + ' · ' : '') + esc(t.name) + (t.total > 0 ? ' · ' + t.done + '/' + t.total : ''));
        for (const st of t.subtasks || []) out.push('        └ ' + icon(st.status) + ' ' + esc(st.name));
      }
    }
  }
  return out;
};
// Budget card: one line per budget line (spent / budget, %, bar, left), then the overall cap. All numbers come from Notion.
const budgetLines = () => {
  const b = item.budget;
  if (!hasBudgetCard) return [];
  const pl = b.lang === 'pl';
  const nf = new Intl.NumberFormat(pl ? 'pl-PL' : 'en-GB', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
  const cur = pl ? ' zł' : ' PLN';
  const money = (v) => (v == null ? '–' : nf.format(v) + cur);
  const eurs = (v) => (v == null ? '' : ' (' + nf.format(v) + ' EUR)');
  const L = pl ? { left: 'zostało', over: 'ponad budżet o', nobudget: 'bez budżetu' } : { left: 'left', over: 'over by', nobudget: 'no budget set' };
  const row = (r, bold) => {
    const out = [];
    const pct = r.budget > 0 ? Math.round(r.spent / r.budget * 100) : null;
    out.push((bold ? '💶 ' : '▫️ ') + '<b>' + esc(r.name) + '</b> · ' + money(r.spent) + ' / ' + money(r.budget) + (pct != null ? ' · ' + pct + '%' : ''));
    if (r.budget > 0) {
      const left = r.budget - r.spent;
      out.push('      ' + budgetBar(pct) + ' ' + (left >= 0 ? L.left + ' ' + money(left) + eurs(r.leftEur) : L.over + ' ' + money(-left) + eurs(r.leftEur == null ? null : -r.leftEur)));
    } else out.push('      <i>' + L.nobudget + '</i>');
    return out;
  };
  const out = ['💶 <b>' + esc(String(b.title || '').toUpperCase()) + '</b>'];
  for (const r of b.rows) out.push(...row(r, false));
  if (b.overall) { out.push(''); out.push(...row(b.overall, true)); }
  return out;
};

// Assemble. Too long for one Telegram message: split between whole lines; the hand-off line stays at the very end.
const head = HEAD[agent] && !isError ? HEAD[agent][0] + ' <b>' + HEAD[agent][1] + '</b> · ' + esc($now.setLocale('en').toFormat('ccc d LLL')) : '';
const cards = [].concat(progressLines(), budgetLines().length && progressLines().length ? [''] : [], budgetLines());
const card = structured || cards.length > 0;
const top = head ? [head].concat(card ? [DIV] : []) : [];
const tail = [].concat(card && head ? [DIV] : [], handoff ? ['', inline(handoff)] : []);
const all = top.concat(body, cards.length && body.length ? [''] : [], cards);
const len = (arr) => arr.join('\n').length;
const tidy = (arr) => arr.join('\n').replace(/\n{3,}/g, '\n\n').trim();
let first = all, rest = [];
if (len(all) + len(tail) > LIMIT) {
  first = [];
  let i = 0;
  for (; i < all.length; i++) { if (len(first.concat([all[i]])) > LIMIT - 40) break; first.push(all[i]); }
  rest = all.slice(i);
  while (rest.length && rest[0] === '') rest.shift();
  if (len(rest) + len(tail) > LIMIT) {
    const kept = [];
    for (const l of rest) { if (len(kept.concat([l])) + len(tail) > LIMIT - 120) break; kept.push(l); }
    rest = kept.concat(['', '<i>… more lines than two Telegram messages hold; ask for fewer days</i>']);
  }
}
const telegram_text = rest.length ? tidy(first.concat(['', '<i>(continues ⬇️)</i>'])) : tidy(first.concat(tail));
const telegram_rest = rest.length ? tidy(rest.concat(tail)) : '';
return { json: { ...item, output: original, telegram_text, telegram_plain: plainOf(telegram_text), telegram_rest, telegram_rest_plain: plainOf(telegram_rest) } };
